"use client"

/**
 * Clean-room event detail. Detail and participants, plus host callbacks.
 * This file does not fetch and does not mutate the event.
 */

import * as React from "react"
import { DoorOpen, FileText, Link2, ListChecks, MapPin, Video, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  formatInterval,
  participantStatusLabel,
  resolveAgendaLabels,
  type AgendaCategory,
  type AgendaEvent,
  type AgendaLabels,
  type AgendaParticipantStatus,
} from "@/lib/agenda"

export type AgendaDetailProps<TMeta = Record<string, unknown>> = {
  event: AgendaEvent<TMeta>
  category?: AgendaCategory | null
  locale?: string
  timeZone?: string
  labels?: Partial<AgendaLabels>
  readOnly?: boolean
  onJoin?: (id: string) => void
  onOpenSummary?: (id: string) => void
  onCreateRoom?: (id: string) => void
  onOpenTask?: (id: string, taskId: string) => void
  onOpenRecord?: (id: string, recordId: string) => void
  onClose?: () => void
  className?: string
}

function statusVariant(status: AgendaParticipantStatus): "default" | "secondary" | "outline" {
  if (status === "confirmed") return "default"
  if (status === "pending") return "secondary"
  return "outline"
}

export function AgendaDetail<TMeta extends Record<string, unknown> = Record<string, unknown>>({
  event,
  category,
  locale = "es-MX",
  timeZone = "America/Mexico_City",
  labels: labelOverrides,
  readOnly = false,
  onJoin,
  onOpenSummary,
  onCreateRoom,
  onOpenTask,
  onOpenRecord,
  onClose,
  className,
}: AgendaDetailProps<TMeta>) {
  const labels = resolveAgendaLabels(labelOverrides)
  const when = formatInterval(event.startsAt, event.endsAt, timeZone, locale, event.allDay)
  const participants = event.participants ?? []

  return (
    <section data-slot="agenda-detail" aria-label={event.title} className={cn("flex flex-col gap-3 p-3", className)}>
      <div className="flex items-start justify-between gap-2">
        <p className="text-xs text-muted-foreground tabular-nums">{when}</p>
        {onClose ? (
          <Button type="button" variant="ghost" size="icon-sm" className="size-6" onClick={onClose} aria-label={labels.closeDetail}>
            <X aria-hidden />
          </Button>
        ) : null}
      </div>
      <Tabs defaultValue="detail">
        <TabsList className="w-full">
          <TabsTrigger value="detail">{labels.detailTab}</TabsTrigger>
          <TabsTrigger value="participants">{labels.participantsTab}</TabsTrigger>
        </TabsList>
        <TabsContent value="detail" className="mt-3 grid gap-2">
          <p className="text-sm break-words whitespace-pre-wrap" dir="auto">
            {event.description?.trim() ? event.description : labels.noDescription}
          </p>
          <dl className="grid gap-1 text-xs text-muted-foreground">
            {category ? (
              <div className="flex gap-2">
                <dt>{labels.categories}</dt>
                <dd className="text-foreground">{category.label}</dd>
              </div>
            ) : null}
            {event.location ? (
              <div className="flex gap-2">
                <dt className="inline-flex items-center gap-1">
                  <MapPin className="size-3.5" aria-hidden />
                  {labels.location}
                </dt>
                <dd className="text-foreground break-words" dir="auto">
                  {event.location}
                </dd>
              </div>
            ) : null}
          </dl>
        </TabsContent>
        <TabsContent value="participants" className="mt-3">
          {participants.length === 0 ? (
            <p className="text-sm text-muted-foreground">{labels.noParticipants}</p>
          ) : (
            <ul className="grid gap-2">
              {participants.map((person) => {
                const status = participantStatusLabel(person.status, labels)
                return (
                  <li key={person.id} className="flex items-center justify-between gap-2 text-sm" aria-label={labels.participantLine(person.name, status)}>
                    <span className="min-w-0 truncate" dir="auto">
                      {person.name}
                    </span>
                    <Badge variant={statusVariant(person.status)}>{status}</Badge>
                  </li>
                )
              })}
            </ul>
          )}
        </TabsContent>
      </Tabs>
      <div className="flex flex-wrap gap-1.5">
        {onJoin ? (
          <Button type="button" size="sm" disabled={readOnly} onClick={() => onJoin(event.id)}>
            <Video aria-hidden />
            {labels.join}
          </Button>
        ) : null}
        {onOpenSummary ? (
          <Button type="button" size="sm" variant="outline" onClick={() => onOpenSummary(event.id)}>
            <FileText aria-hidden />
            {labels.openSummary}
          </Button>
        ) : null}
        {onCreateRoom ? (
          <Button type="button" size="sm" variant="outline" disabled={readOnly} onClick={() => onCreateRoom(event.id)}>
            <DoorOpen aria-hidden />
            {labels.createRoom}
          </Button>
        ) : null}
        {event.taskId && onOpenTask ? (
          <Button type="button" size="sm" variant="outline" onClick={() => onOpenTask(event.id, event.taskId!)}>
            <ListChecks aria-hidden />
            {labels.openTask}
          </Button>
        ) : null}
        {event.recordId && onOpenRecord ? (
          <Button type="button" size="sm" variant="outline" onClick={() => onOpenRecord(event.id, event.recordId!)}>
            <Link2 aria-hidden />
            {labels.openRecord}
          </Button>
        ) : null}
      </div>
    </section>
  )
}

export const RANGE_OPTIONS = [
  { key: "today", label: "Today" },
  { key: "7d", label: "Last 7 days" },
  { key: "30d", label: "Last 30 days" },
  { key: "90d", label: "Last 90 days" },
  { key: "12m", label: "Last 12 months" },
] as const

export type RangeKey = (typeof RANGE_OPTIONS)[number]["key"]

export type ResolvedRange = {
  key: RangeKey
  label: string
  from: number
  to: number
  prevFrom: number
  prevTo: number
  bucket: "hour" | "day" | "month"
}

const DAY = 86_400_000

export function isRangeKey(value: string): value is RangeKey {
  return RANGE_OPTIONS.some((option) => option.key === value)
}

/** Offset of `timeZone` at `ts`, in ms. UTC is 0. */
export function timeZoneOffsetMs(timeZone: string, ts: number): number {
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(ts))
  const parts = Object.fromEntries(formatted.map((part) => [part.type, part.value]))
  const asUtc = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour) % 24,
    Number(parts.minute),
    Number(parts.second),
  )
  return asUtc - ts
}

/** Move a zoned midnight by whole calendar days, including 23h and 25h DST days. */
export function addZonedDays(dayStart: number, days: number, timeZone = "UTC"): number {
  return startOfZonedDay(dayStart + days * DAY + 12 * 3_600_000, timeZone)
}

export function startOfZonedDay(ts: number, timeZone = "UTC"): number {
  const offset = timeZoneOffsetMs(timeZone, ts)
  const local = ts + offset
  const midnightLocal = Math.floor(local / DAY) * DAY
  const guess = midnightLocal - timeZoneOffsetMs(timeZone, midnightLocal - offset)
  const check = timeZoneOffsetMs(timeZone, guess)
  return midnightLocal - check
}

export function resolveRange(
  key: RangeKey,
  now = Date.now(),
  timeZone = "UTC",
): ResolvedRange {
  const option = RANGE_OPTIONS.find((item) => item.key === key) ?? RANGE_OPTIONS[1]
  const today = startOfZonedDay(now, timeZone)
  let from = today
  let bucket: ResolvedRange["bucket"] = "day"
  let span = DAY

  if (key === "today") {
    from = today
    bucket = "hour"
    span = addZonedDays(today, 1, timeZone) - today
  } else if (key === "12m") {
    const offset = timeZoneOffsetMs(timeZone, today)
    const local = new Date(today + offset)
    const start = Date.UTC(local.getUTCFullYear(), local.getUTCMonth() - 11, 1)
    from = start - timeZoneOffsetMs(timeZone, start - offset)
    bucket = "month"
    span = now - from
  } else {
    const days = key === "7d" ? 7 : key === "30d" ? 30 : 90
    from = addZonedDays(today, -(days - 1), timeZone)
    span = addZonedDays(today, 1, timeZone) - from
    bucket = "day"
  }

  return {
    key: option.key,
    label: option.label,
    from,
    to: now,
    prevFrom: from - span,
    prevTo: now - span,
    bucket,
  }
}

/** Inclusive window. */
export function inRange(ts: number, from: number, to: number): boolean {
  return ts >= from && ts <= to
}

export function filterByRange<T>(
  rows: readonly T[],
  getTime: (row: T) => number | null,
  from: number,
  to: number,
): T[] {
  return rows.filter((row) => {
    const ts = getTime(row)
    return ts != null && inRange(ts, from, to)
  })
}

export type DatePreset = {
  key: string
  label: string
}

export const CALL_PRESETS: DatePreset[] = [
  { key: "any", label: "Any time" },
  { key: "today", label: "Today" },
  { key: "tomorrow", label: "Tomorrow" },
  { key: "next7", label: "Next 7 days" },
  { key: "next30", label: "Next 30 days" },
  { key: "last7", label: "Last 7 days" },
  { key: "last30", label: "Last 30 days" },
]

/** `[from, to)` for a named preset, or null when the preset does not filter. */
export function presetBounds(
  preset: string,
  now = Date.now(),
  timeZone = "UTC",
): [number, number] | null {
  const today = startOfZonedDay(now, timeZone)
  switch (preset) {
    case "today":
      return [today, addZonedDays(today, 1, timeZone)]
    case "tomorrow":
      return [addZonedDays(today, 1, timeZone), addZonedDays(today, 2, timeZone)]
    case "next7":
      return [now, now + 7 * DAY]
    case "next30":
      return [now, now + 30 * DAY]
    case "last7":
      return [now - 7 * DAY, now]
    case "last30":
      return [now - 30 * DAY, now]
    case "last90":
      return [now - 90 * DAY, now]
    default:
      return null
  }
}
